namespace ghidra.file.formats.dump;



using ghidra.app.util.bin;
using ghidra.app.util.bin;

public class DumpFileReader : BinaryReader {

	private int size;

	public DumpFileReader(ByteProvider provider, bool isLittleEndian, int size) : base(provider, isLittleEndian)
    {
		this.size = size;
	}

	public long readNextPointer()
    {
		return size == 32 ? readNextInt() : readNextLong();
	}

	public long readPointer(long offset)
    {
		return size == 32 ? readInt(offset) : readLong(offset);
	}

	public int getPointerSize() {
		return size / 8;
	}

	public void setPointerSize(int size) {
		this.size = size;
	}

}
